contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _rewardToken) public payable {
        require(_rewardToken != address(0), "zero token");

        uint256 baseIndex = 0;
        address beforeReward0;
        bool hasBefore;
        (bool okBefore, bytes memory dataBefore) = address(c).staticcall(abi.encodeWithSignature("rewardTokens(uint256)", baseIndex));
        if (okBefore && dataBefore.length >= 32) {
            beforeReward0 = abi.decode(dataBefore, (address));
            hasBefore = true;
        }

        (bool okBeforeData, bytes memory dataBeforeData) = address(c).staticcall(abi.encodeWithSignature("rewardData(address)", _rewardToken));
        require(okBeforeData, "rewardData read failed");
        (uint40 lastUpdateTimeBefore, uint216 rewardRateBefore, uint40 periodFinishBefore, uint216 rewardPerTokenStoredBefore) = abi.decode(dataBeforeData, (uint40,uint216,uint40,uint216));

        bool reverted;
        try c.addReward(_rewardToken) { reverted = false; } catch { reverted = true; }

        (bool okAfterData, bytes memory dataAfterData) = address(c).staticcall(abi.encodeWithSignature("rewardData(address)", _rewardToken));
        require(okAfterData, "rewardData read after failed");
        (uint40 lastUpdateTimeAfter, uint216 rewardRateAfter, uint40 periodFinishAfter, uint216 rewardPerTokenStoredAfter) = abi.decode(dataAfterData, (uint40,uint216,uint40,uint216));

        bool sameAfter;
        if (hasBefore) {
            (bool okAfter, bytes memory dataAfter) = address(c).staticcall(abi.encodeWithSignature("rewardTokens(uint256)", baseIndex));
            require(okAfter, "rewardTokens read after failed");
            address afterReward0 = abi.decode(dataAfter, (address));
            sameAfter = (afterReward0 == beforeReward0);
        } else {
            (bool okAfter, bytes memory dataAfter) = address(c).staticcall(abi.encodeWithSignature("rewardTokens(uint256)", baseIndex));
            sameAfter = !okAfter;
        }

        assert(
            reverted
                ? sameAfter
                    && lastUpdateTimeBefore == lastUpdateTimeAfter
                    && rewardRateBefore == rewardRateAfter
                    && periodFinishBefore == periodFinishAfter
                    && rewardPerTokenStoredBefore == rewardPerTokenStoredAfter
                : true
        );
    }

    receive() external payable {}
}

