contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 stakeForAmount, uint256 withdrawAmount) public {
        require(stakeAmount > 0, "stakeAmount must be > 0");
        require(stakeForAmount > 0, "stakeForAmount must be > 0");

        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        uint256 contractBalanceBefore = c.stakingToken().balanceOf(address(c));

        // First: a general stake call; if it succeeds, invariants hold.
        bool stakeReverted;
        try c.stake(stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        uint256 balanceAfterStake = c.balanceOf(address(this));
        uint256 supplyAfterStake = c.totalSupply();
        uint256 contractBalanceAfterStake = c.stakingToken().balanceOf(address(c));

        // Second: stakeFor; must be equivalent to stake for the caller.
        bool stakeForReverted;
        try c.stakeFor(address(this), stakeForAmount) {
            stakeForReverted = false;
        } catch {
            stakeForReverted = true;
        }

        uint256 balanceAfterStakeFor = c.balanceOf(address(this));
        uint256 supplyAfterStakeFor = c.totalSupply();
        uint256 contractBalanceAfterStakeFor = c.stakingToken().balanceOf(address(c));

        // Third: withdrawAll(true) must never leave a negative balance (impossible in uint256,
        // but the cast to int256 would underflow) and must not revert if balance is zero only.
        bool withdrawReverted;
        try c.withdrawAll(true) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint256 balanceAfterWithdraw = c.balanceOf(address(this));
        uint256 supplyAfterWithdraw = c.totalSupply();

        // General rule: successful stakeFor changes balance/supply/contract balance exactly;
        // failed stakeFor changes nothing; withdrawAll never increases balance/supply beyond
        // the previous successful staking; totalSupply always equals sum of balances (if we
        // had another user, but here it's just this); and balance never grows after withdraw.
        assert(
            (stakeReverted
                ? balanceAfterStake == balanceBefore &&
                  supplyAfterStake == supplyBefore &&
                  contractBalanceAfterStake == contractBalanceBefore
                : balanceAfterStake == balanceBefore + stakeAmount &&
                  supplyAfterStake == supplyBefore + stakeAmount &&
                  contractBalanceAfterStake == contractBalanceBefore + stakeAmount) &&
