contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 stakeAmount,
        uint256 withdrawAmount,
        bool claim,
        address user
    ) public {
        require(user != address(0), "user zero");
        require(stakeAmount > 0, "stake zero");

        // Setup: user needs tokens and approval; use this contract's balance? No token mint.
        // We cannot mint tokens. Assume this contract already holds enough tokens and has approved c?
        // Actually stakeFor transfers from msg.sender (this contract).
        // We need c to have stakingToken balance and allowance.
        // Since we can't mint, we rely on the test harness having funded this contract.
        // But general rule must hold for all inputs; we need c.totalSupply() == sum of balances.
        // We can at least check that after any operation the invariant holds.

        // Read initial totalSupply
        uint256 tsBefore = c.totalSupply();

        // Perform a stake
        c.stakeFor(user, stakeAmount);

        // After stake, totalSupply must equal tsBefore + stakeAmount
        uint256 tsAfterStake = c.totalSupply();
        assert(tsAfterStake == tsBefore + stakeAmount);

        // Read user's balance
        uint256 userBal = c.balanceOf(user);
        assert(userBal >= stakeAmount);

        // Withdraw some amount
        uint256 actualWithdraw = withdrawAmount;
        if (actualWithdraw > userBal) {
            actualWithdraw = userBal;
        }
        if (actualWithdraw > 0) {
            c.withdrawFor(user, actualWithdraw, claim);
            uint256 tsAfterWithdraw = c.totalSupply();
            assert(tsAfterWithdraw == tsAfterStake - actualWithdraw);
        }

        // Final invariant: totalSupply equals sum of balances of all known users? We only know this user.
        // But we can assert that totalSupply after operations equals tsBefore + stakeAmount - actualWithdraw
        uint256 tsFinal = c.totalSupply();
        assert(tsFinal == tsBefore + stakeAmount - actualWithdraw);
    }

    receive() external payable {}
}

