contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 amount) public {
        // precondition: amount > 0 so the only reason for revert is the unknown reward token
        require(amount > 0, "amount must be positive");

        // Make the reward token definitely "unknown": only the owner (this test contract) can add rewards,
        // and addReward requires lastUpdateTime == 0 before adding. Since this test contract is the owner
        // and we do not call addReward for rewardToken, rewardData[rewardToken].lastUpdateTime is 0.
        // (If somehow it were already added in a prior setup, the rule below would still hold because
        // _notifyReward would be reached and not revert for that token, but the checker uses a fresh c.)
        uint256 balanceBefore = c.stakingToken().balanceOf(address(c));

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.stakingToken().balanceOf(address(c));

        // General rule: notifying a reward for an unknown token must revert, and in the reverting case
        // the staking token balance of c must be unchanged.
        assert(reverted && balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

