        address rewardTokenAddr,
        address distributor,
        uint256 rewardAmount,
        uint256 stakeAmount,
        uint256 withdrawAmount
    ) public {
        require(rewardAmount > 0, "rewardAmount must be > 0");

        // Drive the contract to a state with a known reward token and a staker.
        c.setRewardDistributor(distributor);
        c.addReward(rewardTokenAddr);

        // Stake some amount (requires the staking token to have been transferred to the test contract beforehand).
        if (stakeAmount > 0) {
            c.stake(stakeAmount);
        }

        // Only attempt to notify the reward if we are the distributor.
        if (msg.sender == address(this)) {
            // We are the test contract; the only way to be distributor is if the caller passed itself.
            c.notifyRewardAmount(rewardTokenAddr, rewardAmount);
        }

        // Read the reward token balance held by the staking contract.
        uint256 rewardTokenBalance = IERC20(rewardTokenAddr).balanceOf(address(c));

        // Attempt to claim rewards for the staker (the test contract).
        bool reverted;
        try c.getReward(address(this), rewardTokenAddr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The amount of reward token paid out must not exceed the balance that was held.
        // After the call, the contract's balance of the reward token must be non-negative,
        // i.e. the balance before minus the amount paid (which is the drop in balance) must be >= 0.
        // Since we don't have a direct getter for the amount paid, we can check that the balance
