contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 stakeAmount, uint256 withdrawAmount) public {
        require(stakeAmount > 0, "stakeAmount must be > 0");
        require(withdrawAmount > 0, "withdrawAmount must be > 0");
        require(withdrawAmount <= stakeAmount, "withdrawAmount must be <= stakeAmount");

        // Approve the staking token so the test contract can stake.
        // We assume the staking token is already deployed and the test contract holds enough.
        // The staking token address is obtained from c's public getter.
        address stakingTokenAddr = address(c.stakingToken());

        // Give the test contract staking tokens by transferring from itself? Not possible.
        // Instead, we rely on the test contract being pre-funded with staking tokens.
        // Approve c to spend the staking tokens.
        // This is a call on the staking token, not on c, but we need it for setup.
        // The staking token is an external contract; we can call it directly.
        // However, the constraint says we interact only through c. But staking requires approval.
        // Since we cannot call approve on the staking token without an interface, we omit it.
        // The test assumes the test contract already has an allowance to c.
        // Actually, stakingToken.safeTransferFrom(msg.sender, address(this), amount) is called by c,
        // so the test contract must have approved c beforehand. We cannot do that here without
        // an interface to the staking token. So we must require that the allowance exists.
        // But we cannot check allowance without an interface. We'll just try to stake and catch.

        // Read the initial stake of the test contract.
        uint256 initialStake = c.balanceOf(address(this));

        // Stake the amount. This may revert if allowance is insufficient.
        // We use try/catch to handle the revert.
        bool stakeReverted;
        try c.stake(stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // If staking reverted, we cannot proceed with the withdraw rule.
        // We assert that if staking reverted, the balance remains unchanged.
        // But the property is about successful withdraw. We can still assert something general.
        // However, the checker will try to prove the rule for all inputs; if staking reverts, the rule
        // should still hold trivially. But we want a meaningful rule.
        // Let's require that staking did not revert as a precondition? That would make the test
        // only meaningful if staking succeeds. But we cannot require it because we don't control
        // the initial allowance. The checker will explore inputs; if it finds a reverting case,
        // the assert might still hold if we design it carefully.

        // We'll design the rule to hold regardless of whether staking reverted, by only
        // asserting the relationship when both staking and withdrawal succeed.
        // But the assert must be a single formula. We can use the revert flags as booleans.

        // Read the staking token balance of c before withdrawal.
        uint256 contractBalanceBefore = c.balanceOf(address(this));

        // Attempt to withdraw.
        bool withdrawReverted;
        try c.withdraw(withdrawAmount, false) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Read the staking token balance of c after withdrawal.
        uint256 contractBalanceAfter = c.balanceOf(address(this));

        // General rule: if both stake and withdraw succeeded, then the staker's balance decreased
        // by exactly withdrawAmount, and the contract's token balance decreased by exactly withdrawAmount.
        // However, we don't have direct access to the token balance of the contract (only the staker's).
        // We can only observe c.balanceOf(address(this)).
        // So the rule is: after a successful withdraw, balanceOf(address(this)) == balanceBefore - withdrawAmount.
        // Also, if stake reverted, then balanceBefore == initialStake, and after withdraw (which may or may not revert),
        // the balance should be consistent.

        // Let's define the assertion: If withdraw did not revert, then the staker's balance decreased by withdrawAmount.
        // Additionally, if stake did not revert, then the balance before withdraw should be initialStake + stakeAmount.
        // We'll combine into one assert.
        // We need to avoid subtraction underflow in the assert. We can use the fact that
        // if withdrawReverted is false, then contractBalanceBefore >= withdrawAmount (since it succeeded).
        // So contractBalanceBefore - withdrawAmount is safe.

        // The rule: (withdrawReverted || contractBalanceAfter == contractBalanceBefore - withdrawAmount)
        // AND (stakeReverted || contractBalanceBefore == initialStake + stakeAmount)
        // But we want a single assert. We can use logical AND.

        bool rule1 = withdrawReverted || (contractBalanceAfter == contractBalanceBefore - withdrawAmount);
        bool rule2 = stakeReverted || (contractBalanceBefore == initialStake + stakeAmount);

        assert(rule1 && rule2);
    }
}

