    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 amount) public payable {
        require(staker != address(0), "staker zero");
        require(amount > 0, "amount zero");

        uint256 beforeBal = c.balanceOf(staker);
        uint256 beforeTotal = c.totalSupply();

        bool reverted;
        try c.stakeFor(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = c.balanceOf(staker);
        uint256 afterTotal = c.totalSupply();

        assert(
            (!reverted && afterBal == beforeBal + amount && afterTotal == beforeTotal + amount)
            || (reverted && afterBal == beforeBal && afterTotal == beforeTotal)
        );
    }

    receive() external payable {}
}

