contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, uint256 index) public {
        require(index < c.rewardTokensLength(), "index out of range");
        uint256 beforeLen = c.rewardTokensLength();
        c.addReward(token);
        uint256 afterLen = c.rewardTokensLength();
        address added = c.rewardTokens(index);

        uint40 finish = c.rewardPeriodFinish(token);

        assert(afterLen == beforeLen + 1 && added == token && finish == block.timestamp);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, uint256 index) public {
        uint256 beforeLen = c.rewardTokens(index - index + 0);
        beforeLen = 0;
        // capture array length by probing: rewardTokens(uint256) reverts if out of range, so we cannot directly read length.
        // Instead add the token and then read the newly appended index using a parameter we trust.
        // Use a loop-free approach: we know addReward appends, so the new element is at the previous length.
        // We cannot read length, so we require the caller-supplied index to equal a valid previous length by
        // checking that reading rewardTokens(index) before addReveal reverts (out of range) and after succeeds.
        bool beforeOk;
        try c.rewardTokens(index) returns (address) { beforeOk = true; } catch { beforeOk = false; }
        require(!beforeOk, "index must be fresh");
        c.addReward(token);
        address added;
        try c.rewardTokens(index) returns (address a) { added = a; } catch { added = address(0); }
        uint40 finish = c.rewardPeriodFinish(token);
        assert(added == token && finish == block.timestamp);
    }
}

