contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _for, uint256 _amount) public payable {
        require(_amount > 0);
        require(_for != address(0));

        // We do not care about the staking token transfer succeeding for the state of c itself;
        // call stakeFor and observe the effect on c's public accounting.
        uint256 balBefore = c.balanceOf(_for);
        uint256 totalBefore = c.totalSupply();

        c.stakeFor(_for, _amount);

        uint256 balAfter = c.balanceOf(_for);
        uint256 totalAfter = c.totalSupply();

        assert(totalAfter == totalBefore + _amount);
        assert(balAfter == balBefore + _amount);
    }

    receive() external payable {}
}

