contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        require(amount > 0);

        // Give the test contract tokens to stake. Assumes the staking token is a public
        // getter returning an IERC20-like interface, and permit/approve is not required here.
        // We only observe c through its public surface and the staking token's public surface.
        IERC20 token = c.stakingToken();
        // Assume the test contract is pre-funded and has approved c. The checker's fresh deployment
